#include "dial-prefix-buckets.h"

std::optional<std::map<std::string,std::vector<std::string>>> charm::v1n7::phone_number::bucket_by_longest_prefix(const std::vector<std::string>& numbers,const std::vector<std::string>& prefixes){std::set<std::string> unique;for(const auto& prefix:prefixes){if(prefix.empty()||!std::all_of(prefix.begin(),prefix.end(),[](unsigned char c){return std::isdigit(c);})||!unique.insert(prefix).second)return std::nullopt;}std::map<std::string,std::vector<std::string>> out;for(const auto& number:numbers){if(number.empty()||!std::all_of(number.begin(),number.end(),[](unsigned char c){return std::isdigit(c);}))return std::nullopt;const std::string* best=nullptr;for(const auto& prefix:prefixes)if(number.rfind(prefix,0)==0&&(!best||prefix.size()>best->size()))best=&prefix;if(!best)return std::nullopt;out[*best].push_back(number);}return out;}
